add_action( 'homepage', 'perfectpixel_storefront_homepage_slider', 5 );

function perfectpixel_storefront_homepage_slider() {
	$shortcode = trim( '{{storefront_slider_shortcode}}' );
	if ( '' === $shortcode ) {
		return;
	}
	echo '<div class="perfectpixel-homepage-slider" style="width:100vw;position:relative;left:50%;margin-left:-50vw;margin-bottom:2.5em">' . do_shortcode( $shortcode ) . '</div>';
}
